	"Signed-off-by: A <a@example.com>", "Entire-Checkpoint: deadbeefcafe", "Co-Authored-By: B <b@example.com>",
	"  Entire-Checkpoint: deadbeefcafe", "\tEntire-Checkpoint: deadbeefcafe",
	" continuation text", "\tcontinuation text",
	"# a comment line", "#",
	"Signed-off-by: A <a@example.com>\r", "\r",
}

func randomMessage(r *rand.Rand) string {
	n := 1 + r.Intn(7)
	lines := make([]string, n)
	for i := range lines {
		lines[i] = vocab[r.Intn(len(vocab))]
	}
	msg := strings.Join(lines, "\n")
	if r.Intn(2) == 0 {
		msg += "\n"
	}
	return msg
}

func gitParse(t *testing.T, msg string) string {
	t.Helper()
	cmd := exec.Command("git", "-c", "core.commentChar=#", "interpret-trailers", "--parse")
	cmd.Stdin = strings.NewReader(msg)
	out, err := cmd.Output()
	if err != nil {
		t.Fatalf("git interpret-trailers: %v", err)
	}
	return string(out)
}

func TestPropWriterReaderRoundtrip(t *testing.T) {
	r := rand.New(rand.NewSource(1))
	const id = "abc123def456"
	readerMiss, gitMiss, joined := 0, 0, 0
	gitChecked := 0
	for i := 0; i < 20000; i++ {
		msg := randomMessage(r)
		got := AppendCheckpointTrailer(msg, id)
		if !strings.Contains(got, "\n\nEntire-Checkpoint: "+id) && strings.TrimRight(msg, "\n") != "" {
			joined++
		}
		found := false
		for _, c := range ParseAllCheckpointsFromFinalTrailerBlock(got) {
			if c.String() == id {
				found = true
			}
		}
		if !found {
			readerMiss++
			if readerMiss <= 5 {
				t.Errorf("reader miss: in=%q out=%q", msg, got)
			}
		}
		if i%40 == 0 {
			gitChecked++
			if !strings.Contains(gitParse(t, got), "Entire-Checkpoint: "+id) {
				gitMiss++
				if gitMiss <= 5 {
					t.Logf("git miss: in=%q out=%q", msg, got)
				}
			}
		}
	}
	t.Logf("cases=20000 joined=%d readerMiss=%d gitChecked=%d gitMiss=%d", joined, readerMiss, gitChecked, gitMiss)
}

