func zzPostCommit(t *testing.T, message string, seedForged bool) {
	dir := setupGitRepo(t)
	t.Chdir(dir)
	ctx := context.Background()
	repo, err := git.PlainOpen(dir)
	require.NoError(t, err)
	s := &ManualCommitStrategy{}
	sessionID := "test-postcommit-forged"
	setupSessionWithCheckpoint(t, s, repo, dir, sessionID)

	forged := id.MustCheckpointID(zzForged)
	if seedForged {
		store := cpkg.NewGitStore(repo, cpkg.DefaultV1Refs())
		require.NoError(t, store.Write(ctx, cpkg.Session{
			CheckpointID: forged, SessionID: "unrelated-session", Strategy: "manual-commit",
			Transcript: redact.AlreadyRedacted([]byte("unrelated transcript\n")),
			AuthorName: "Test", AuthorEmail: "test@example.com",
		}))
	}

	state, err := s.loadSessionState(ctx, sessionID)
	require.NoError(t, err)
	state.Phase = session.PhaseActive
	require.NoError(t, s.saveSessionState(ctx, state))
	before := state.StepCount

	wt, err := repo.Worktree()
	require.NoError(t, err)
	_, err = wt.Add("test.txt")
	require.NoError(t, err)
	_, err = wt.Commit(message, &git.CommitOptions{
		Author: &object.Signature{Name: "Test", Email: "test@test.com", When: time.Now()},
	})
	require.NoError(t, err)
	require.NoError(t, s.PostCommit(ctx))

	state, err = s.loadSessionState(ctx, sessionID)
	require.NoError(t, err)
	store := cpkg.NewGitStore(repo, cpkg.DefaultV1Refs())
	summary, readErr := store.Read(ctx, forged)
	sessions := -1
	if readErr == nil && summary != nil {
		sessions = len(summary.Sessions)
	}
	var ids []string
	for _, sid := range func() []string {
		if readErr != nil || summary == nil {
			return nil
		}
		out := []string{}
		for i := range summary.Sessions {
			c, err := store.ReadSessionContent(ctx, forged, i)
			if err == nil {
				out = append(out, c.Metadata.SessionID)
			}
		}
		return out
	}() {
		ids = append(ids, sid)
	}
	t.Logf("StepCount before=%d after=%d LastCheckpointID=%s forged-checkpoint sessions=%d ids=%v",
		before, state.StepCount, state.LastCheckpointID, sessions, ids)
}

